#!/usr/bin/env bash
# Publish the listening pages and their renders to the public bucket (default gs://gm-procedural).
# Uploads html/mp3/png/json and the hand-made pages' wav clips. Never uploads banks (*.dls, *.sf2), MIDI, logs or the
# renderer binary. Usage: tools/publish.sh [--dry-run]
set -euo pipefail
cd "$(dirname "$0")/.."
B="${GM_BUCKET:-gs://gm-procedural}"
DRY=(); [[ "${1:-}" == "--dry-run" ]] && DRY=(--dry-run)
NEVER='.*\.(dls|DLS|sf2|mid|MID|zip|ZIP|log|txt|TXT|1ST|DIZ|ION)$|.*gmrender$|(^|.*/)banks/.*|(^|.*/)midi/.*'

# Song A/B + all-sounds pages (generated by tools/gm-songs/run.ts page; relative mp3 links).
if [[ -f build/gm/songs/results.0.json || -f build/gm/songs/results.json ]]; then bun tools/gm-songs/run.ts page >/dev/null; fi
if [[ -d build/gm/songs ]]; then
  gcloud storage rsync -r "${DRY[@]}" --exclude="$NEVER|.*\.wav$" build/gm/songs "$B/gm/songs"
  [[ ${#DRY[@]} -eq 0 ]] && gcloud storage objects update "$B/gm/songs/*.html" --cache-control=no-cache >/dev/null
fi

# Hand-made fitting-round pages: HTML from pages/<name>/, audio + sheets from build/gm/<name>/.
for p in pages/*/; do
  n=$(basename "$p")
  if [[ -d "build/gm/$n" ]]; then
    gcloud storage rsync -r "${DRY[@]}" --exclude="$NEVER|.*\.html$" "build/gm/$n" "$B/gm/pages/$n"
  fi
  [[ ${#DRY[@]} -eq 0 ]] && gcloud storage cp --cache-control=no-cache "$p/index.html" "$B/gm/pages/$n/index.html"
done
[[ ${#DRY[@]} -eq 0 ]] && gcloud storage cp --cache-control=no-cache pages/index.html "$B/index.html"
echo "https://storage.googleapis.com/${B#gs://}/index.html"
